<script>
  import { onMount } from 'svelte';
  import { ArrowLeft, ArrowUpRight, BookOpen, Search, SlidersHorizontal, X, ChevronRight, Sparkles, Atom, Globe2, Bookmark, GraduationCap } from 'lucide-svelte';
  let data = $state(null), query = $state(''), subject = $state('all'), grade = $state('all'), field = $state('all'), selected = $state(null), saved = $state([]);
  let records = $derived([...(data?.topicRecords || []), ...(data?.authoredModules || []).map(x => ({...x, authored:true, keyTerms:x.terms, formulas:x.formula ? [x.formula] : [], workedExamples:x.example ? [{question:x.example.q, steps:x.example.work, answer:x.example.a}] : [], commonErrors:x.errors, questionPatterns:x.questionPatterns, explanation:x.explanation}))]);
  let fields = $derived([...new Set(records.filter(x => subject==='all' || x.subject===subject).map(x=>x.field).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja')));
  let shown = $derived(records.filter(x => (subject==='all'||x.subject===subject) && (grade==='all'||String(x.grade)===grade) && (field==='all'||x.field===field) && (!query || [x.title,x.field,x.explanation,...(x.keyTerms||[]).map(t=>Array.isArray(t)?t.join(' '):t)].filter(Boolean).join(' ').toLowerCase().includes(query.toLowerCase()))));
  onMount(async()=>{try{const r=await fetch('/data/knowledge-base.json');if(!r.ok)throw new Error('教材データを読み込めませんでした');data=await r.json();saved=JSON.parse(localStorage.getItem('manabixx-library-saved')||'[]');}catch(e){console.error(e);}});
  function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('manabixx-library-saved',JSON.stringify(saved));}
</script>
<svelte:head><title>教材ライブラリ — MANABIXX</title><meta name="description" content="理科・社会の単元、重要語句、公式、実験、典型問題を横断して学べる教材ライブラリ。"/></svelte:head>
<div class="library-shell">
  <header class="top"><a class="brand" href="/"><span class="mark">M<span>.</span></span><span>MANABIXX<small>LEARNING PLATFORM</small></span></a><div class="crumb">LIBRARY <i>/</i> KNOWLEDGE BASE</div><a href="/" class="home-link"><ArrowLeft size={16}/> Studyホーム</a></header>
  <main>
    <section class="intro"><div><div class="eyebrow"><Sparkles size={14}/> KNOWLEDGE ARCHIVE / 01</div><h1>知識を、<em>使える力に。</em></h1><p>単元を探す。仕組みを理解する。解ける知識へ変えていく。</p></div><div class="intro-mark"><BookOpen size={32}/><span>MX / LIBRARY</span></div></section>
    <section class="overview"><div><span>ALL TOPICS</span><strong>{records.length.toLocaleString('ja-JP')}</strong><small>登録コンテンツ</small></div><div><span>SCIENCE</span><strong>{records.filter(x=>x.subject==='science').length}</strong><small>理科</small></div><div><span>SOCIAL STUDIES</span><strong>{records.filter(x=>x.subject==='social').length}</strong><small>社会</small></div><div><span>DETAILED NOTES</span><strong>{records.filter(x=>x.authored||x.status==='authored').length}</strong><small>解説付き教材</small></div></section>
    <div class="catalog-head"><div><div class="eyebrow">EXPLORE CONTENTS</div><h2>教材を探す</h2><p>キーワードや教科、学年から必要な単元へ。</p></div><div class="result-count">{shown.length.toLocaleString('ja-JP')} <small>件を表示</small></div></div>
    <section class="filters"><label class="search"><Search size={18}/><input bind:value={query} placeholder="単元名・用語・内容から検索"/>{#if query}<button onclick={()=>query=''} aria-label="検索をクリア"><X size={15}/></button>{/if}</label><div class="filter-row"><label><span>教科</span><select bind:value={subject}><option value="all">すべて</option><option value="science">理科</option><option value="social">社会</option></select></label><label><span>学年</span><select bind:value={grade}><option value="all">全学年</option><option value="1">中学1年</option><option value="2">中学2年</option><option value="3">中学3年</option></select></label><label><span>分野</span><select bind:value={field}><option value="all">すべての分野</option>{#each fields as f}<option value={f}>{f}</option>{/each}</select></label><button class="clear" onclick={()=>{subject='all';grade='all';field='all';query='';}}>条件をリセット <SlidersHorizontal size={14}/></button></div></section>
    {#if !data}<div class="empty"><div class="loader"></div>教材データを読み込んでいます</div>{:else if shown.length===0}<div class="empty">条件に一致する教材がありません。検索語や絞り込みを変更してください。</div>{:else}
      <div class="cards">{#each shown as item,i}<article class:expanded={selected===item.id}><div class="card-top"><span class:science={item.subject==='science'} class:social={item.subject==='social'} class="subject">{#if item.subject==='science'}<Atom size={13}/> 理科{:else}<Globe2 size={13}/> 社会{/if}</span><span class="grade">中学{item.grade||'全'}年 · {item.field||'総合'}</span><button class:bookmarked={saved.includes(item.id)} class="save" onclick={()=>toggleSave(item.id)} aria-label="保存"><Bookmark size={16}/></button></div><h3>{item.title}</h3><p class="description">{item.explanation || (item.targets?.length ? item.targets.join('・') : 'この単元の重要事項・用語・典型的な考え方を整理するための学習項目です。')}</p><div class="card-bottom"><span class:complete={item.authored||item.status==='authored'}>{item.authored||item.status==='authored'?'DETAILED NOTE':'TOPIC INDEX'}</span><button onclick={()=>selected=selected===item.id?null:item.id}>{selected===item.id?'閉じる':'内容を見る'} <ChevronRight size={15}/></button></div>
        {#if selected===item.id}<div class="detail"><div class="detail-title">学習ポイント</div>{#if item.keyTerms?.length}<h4>重要語句</h4><div class="terms">{#each item.keyTerms as term}<span><b>{Array.isArray(term)?term[0]:term}</b>{#if Array.isArray(term)}<small>{term[1]}</small>{/if}</span>{/each}</div>{/if}{#if item.formulas?.length}<h4>公式・関係</h4>{#each item.formulas as f}<p>{f}</p>{/each}{/if}{#if item.workedExamples?.length}<h4>例題</h4>{#each item.workedExamples as ex}<p class="example-q">{ex.question||ex.q}</p>{#each ex.steps||[] as step,j}<p class="step">{j+1}. {step}</p>{/each}<p class="answer">答え：{ex.answer||ex.a}</p>{/each}{/if}{#if item.commonErrors?.length}<h4>間違えやすいポイント</h4><ul>{#each item.commonErrors as e}<li>{e}</li>{/each}</ul>{/if}{#if item.questionPatterns?.length}<h4>よく問われる視点</h4><ul>{#each item.questionPatterns as p}<li>{p}</li>{/each}</ul>{/if}{#if !item.keyTerms?.length&&!item.formulas?.length&&!item.workedExamples?.length&&!item.commonErrors?.length}<p>この項目の詳細ノートは準備中です。単元の索引として利用できます。</p>{/if}</div>{/if}
      </article>{/each}</div>
    {/if}
    <footer><a href="/">MANABIXX<span>.</span></a><span>KNOWLEDGE THAT MOVES YOU FORWARD.</span><a href="/releases/">更新履歴 <ArrowUpRight size={14}/></a></footer>
  </main>
</div>
<style>
:global(body){background:#f5f6fb}.library-shell{min-height:100vh;background:var(--canvas);color:var(--ink)}.top{height:70px;display:flex;align-items:center;gap:40px;padding:0 max(24px,calc((100vw - 1180px)/2));background:var(--surface);border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font-weight:950;letter-spacing:.04em;font-size:12px}.brand small{display:block;font-size:7px;letter-spacing:1.5px;color:var(--muted);margin-top:3px}.mark{width:31px;height:31px;border-radius:9px;background:#181b2a;color:#fff;display:grid;place-items:center;font-size:15px}.mark span,footer a span{color:#a99dff}.crumb{font-size:8px;letter-spacing:1.6px;color:var(--muted);font-weight:800}.crumb i{font-style:normal;margin:0 8px;color:var(--brand)}.home-link{margin-left:auto;display:flex;align-items:center;gap:7px;font-size:10px;color:var(--muted);font-weight:750}main{max-width:1180px;margin:auto;padding:0 25px 35px}.intro{padding:62px 0 32px;display:flex;justify-content:space-between;align-items:center}.eyebrow{display:flex;align-items:center;gap:8px;color:var(--brand);font-size:8px;letter-spacing:1.8px;font-weight:900}.intro h1{font-size:clamp(34px,5vw,54px);letter-spacing:-2px;margin:15px 0 8px}.intro h1 em{font-style:normal;color:var(--brand)}.intro p,.catalog-head p{font-size:11px;color:var(--muted)}.intro-mark{width:130px;height:130px;border:1px solid var(--line);border-radius:25px;background:linear-gradient(145deg,var(--surface),var(--brand-soft));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:var(--brand)}.intro-mark span{font-size:7px;letter-spacing:1.5px;font-weight:900}.overview{display:grid;grid-template-columns:repeat(4,1fr);background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:18px 0}.overview>div{padding:0 23px;border-right:1px solid var(--line)}.overview>div:last-child{border:0}.overview span,.overview small{display:block;font-size:7px;letter-spacing:1px;color:var(--muted);font-weight:800}.overview strong{display:block;font-size:25px;letter-spacing:-1px;margin:5px 0 1px}.catalog-head{display:flex;align-items:end;justify-content:space-between;margin:42px 0 16px}.catalog-head h2{font-size:22px;margin:8px 0 4px}.catalog-head p{margin:0}.result-count{font-size:22px;font-weight:900;color:var(--brand)}.result-count small{font-size:9px;color:var(--muted);font-weight:600}.filters{background:var(--surface);border:1px solid var(--line);border-radius:13px;padding:16px;margin-bottom:17px}.search{height:43px;border:1px solid var(--line);border-radius:8px;display:flex;align-items:center;gap:10px;padding:0 12px;color:var(--muted)}.search:focus-within{border-color:var(--brand)}.search input{border:0;outline:0;background:transparent;color:var(--ink);width:100%;font-size:10px}.search button{border:0;background:transparent;color:var(--muted)}.filter-row{display:flex;align-items:end;gap:11px;margin-top:12px}.filter-row label{display:grid;gap:5px;font-size:8px;color:var(--muted);font-weight:750}.filter-row select{min-width:130px;height:35px;padding:0 9px;border:1px solid var(--line);border-radius:7px;background:var(--canvas);color:var(--ink);font-size:9px}.clear{margin-left:auto;border:0;background:transparent;color:var(--muted);font-size:8px;display:flex;align-items:center;gap:6px;padding:10px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.cards article{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px;min-width:0;transition:border-color .18s,transform .18s}.cards article:hover{border-color:#aaa1ff;transform:translateY(-2px)}.cards article.expanded{grid-column:span 2;border-color:var(--brand)}.card-top{display:flex;align-items:center;gap:8px}.subject{display:inline-flex;align-items:center;gap:5px;padding:5px 7px;border-radius:5px;font-size:8px;font-weight:850}.subject.science{background:#e8f7f4;color:#168b79}.subject.social{background:#fff1e8;color:#bd7841}.grade{font-size:7px;color:var(--muted)}.save{margin-left:auto;border:0;background:transparent;color:#a0a3b2;padding:4px}.save.bookmarked{color:var(--brand)}.save.bookmarked :global(svg){fill:var(--brand);stroke:var(--brand)}.cards h3{font-size:14px;margin:14px 0 7px;letter-spacing:-.2px}.description{font-size:9px;line-height:1.8;color:var(--muted);min-height:34px;margin:0}.card-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);margin-top:13px;padding-top:10px}.card-bottom>span{font-size:7px;letter-spacing:1px;color:var(--muted);font-weight:850}.card-bottom>span.complete{color:var(--brand)}.card-bottom button{border:0;background:transparent;color:var(--brand);font-size:8px;font-weight:850;display:flex;align-items:center;gap:4px}.detail{border-top:1px solid var(--line);margin-top:13px;padding-top:13px;grid-column:1/-1}.detail-title{font-size:8px;letter-spacing:1px;color:var(--brand);font-weight:900}.detail h4{font-size:9px;margin:14px 0 7px}.detail p,.detail li{font-size:9px;line-height:1.8;color:var(--muted)}.terms{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.terms span{padding:8px;background:var(--canvas);border-radius:6px;font-size:8px}.terms b,.terms small{display:block}.terms small{color:var(--muted);margin-top:3px}.example-q{font-weight:800;color:var(--ink)!important}.step{margin:2px 0!important}.answer{color:var(--brand)!important;font-weight:800}.detail ul{padding-left:17px}.empty{min-height:220px;display:flex;align-items:center;justify-content:center;gap:12px;color:var(--muted);font-size:10px;background:var(--surface);border:1px dashed var(--line);border-radius:13px}.loader{width:18px;height:18px;border:2px solid var(--line);border-top-color:var(--brand);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);margin-top:42px;padding-top:17px;color:var(--muted);font-size:7px;letter-spacing:1.2px}footer a:first-child{font-size:13px;color:var(--ink);font-weight:950}footer a:last-child{display:flex;align-items:center;gap:4px;color:var(--ink);font-weight:800}
@media(max-width:850px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.cards article.expanded{grid-column:span 2}.overview>div{padding:0 13px}.top{gap:20px}}
@media(max-width:580px){.top{height:58px;padding:0 15px}.crumb{display:none}main{padding:0 14px 25px}.intro{padding:42px 0 24px}.intro-mark{width:72px;height:72px;border-radius:15px}.intro-mark svg{width:22px}.intro-mark span{font-size:5px}.intro h1{font-size:31px;letter-spacing:-1px}.intro p{font-size:9px;max-width:260px;line-height:1.8}.overview{grid-template-columns:repeat(2,1fr);gap:14px 0;padding:15px 0}.overview>div:nth-child(2){border:0}.overview>div:nth-child(3){padding-top:10px}.overview>div:nth-child(4){padding-top:10px}.overview strong{font-size:22px}.catalog-head{margin-top:31px}.catalog-head h2{font-size:19px}.filter-row{display:grid;grid-template-columns:1fr 1fr}.filter-row select{width:100%;min-width:0}.clear{margin:0;justify-content:start}.cards{grid-template-columns:1fr}.cards article.expanded{grid-column:span 1}.terms{grid-template-columns:1fr}footer{gap:10px;font-size:5px}footer span{display:none}.home-link{font-size:8px}}
</style>